#!/usr/bin/env python3
"""Optionally regenerate checked-in GPIO/key tables from a matching local dump."""
import argparse
from pathlib import Path
from inspect_firmware import PROJECT_ROOT, FirmwareImage


def generate(path: Path) -> None:
    image = FirmwareImage(path)
    lines = [
        "// Generated by tools/generate_layout.py from the SHA-256-verified backup.",
        "#pragma once", '#include "Protocol.hpp"', "namespace bridge {",
        "struct Pin { uint8_t port; uint8_t bit; };",
        "struct Key { uint8_t kind; uint8_t value; };",
    ]
    for name, address, size in (("kRowPins", 0x55CE, 18), ("kColumnPins", 0x5492, 8)):
        values = [f"{{{image.data[address + size + i]}, {image.data[address + i]}}}" for i in range(size)]
        lines.append(f"constexpr Pin {name}[] = {{" + ", ".join(values) + "};")
    for name, start, count in (("kKeys", 0x54A2, 144), ("kAlternate", 0x55C2, 6)):
        lines.append(f"constexpr Key {name}[] = {{")
        for row in range(0, count, 8):
            values = [f"{{0x{image.data[start + 2*i]:02x}, 0x{image.data[start + 2*i+1]:02x}}}"
                      for i in range(row, min(row + 8, count))]
            lines.append("    " + ", ".join(values) + ",")
        lines.append("};")
    masks = image.data[0x548B:0x5492]
    lines.append("constexpr uint8_t kConsumerMasks[] = {" + ", ".join(f"0x{x:02x}" for x in masks) + "};")
    lines.append("}")
    output = PROJECT_ROOT / "include/bridge/KeyboardLayout.hpp"
    output.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(output.relative_to(PROJECT_ROOT))


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("image", type=Path, help="Your own original LPC Flash dump")
    generate(parser.parse_args().image)
